// Build Alert: turn the Error Trigger payload into a Telegram message (FR-18)
const CHAT_ID = 'REPLACE_WITH_TELEGRAM_CHAT_ID';
if (CHAT_ID === 'REPLACE_WITH_TELEGRAM_CHAT_ID') throw new Error('SET_TELEGRAM_CHAT_ID');

const e = $input.first().json || {};
const ex = e.execution || {};
const wf = e.workflow || {};

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const redact = (s) => String(s)
  .replace(/gsk_[A-Za-z0-9]+/g, '[redacted]')
  .replace(/AIza[0-9A-Za-z_-]+/g, '[redacted]')
  .replace(/ya29\.[0-9A-Za-z._-]+/g, '[redacted]')
  .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, 'Bearer [redacted]')
  .replace(/\b\d{8,}:[A-Za-z0-9_-]{30,}/g, '[redacted]');
const clip = (s, n) => (s.length > n ? s.slice(0, n) + '...' : s);
const safe = (v, n) => esc(clip(redact(v == null || v === '' ? 'unknown' : v), n));

// IST timestamp without Intl
const ist = new Date(Date.now() + 330 * 60000).toISOString().replace('T', ' ').slice(0, 19) + ' IST';

const lines = [
  '🚨 <b>PIPELINE FAULT: OpenLead Automation</b>',
  '',
  '<b>Workflow:</b> ' + safe(wf.name, 120),
  '<b>Failed node:</b> <code>' + safe(ex.lastNodeExecuted, 120) + '</code>',
  '<b>Execution ID:</b> <code>' + safe(ex.id, 40) + '</code>',
  '<b>Mode:</b> ' + safe(ex.mode, 20),
  '<b>Time:</b> ' + ist,
  '<b>Error:</b> <i>' + safe(ex.error && ex.error.message, 500) + '</i>',
  '',
  '<i>Workflow stopped safely. Check the execution log.</i>'
];

return [{ json: { chat_id: CHAT_ID, text: lines.join('\n'), parse_mode: 'HTML' } }];
